INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('3-day-wildlife-quest-machu-wasi', '3-day-wildlife-quest-machu-wasi', '3-Day Wildlife Quest ÔÇô Machu Wasi', 'wildlife', 'activo', 3, 2, 450, 'USD', 2, 8, 'F├ícil', 'Mayo - Octubre (Temporada Seca)', 'Un tour de vida silvestre de 3 d├¡as al Parque Nacional Manu, ideal para quienes tienen poco tiempo pero quieren experimentar la Amazon├¡a peruana.', 'Este tour de 3 d├¡as es perfecto para quienes quieren experimentar la selva amaz├│nica sin alejarse demasiado. Viajamos en van por el bosque nuboso, descendemos hasta la selva baja y exploramos los r├¡os en bote buscando caimanes, capybaras y aves ex├│ticas en Machu Wasi.', '/media/1786591103305-pteronura-brasiliensis-zoo-brasilia-01.jpg', '3-Day Wildlife Quest at Machu Wasi ÔÇô Manu National Park', '[{"url":"assets/media_to_upload/photos/placeholder.jpg","alt":"Wildlife at Machu Wasi"}]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest ÔåÆ Machu Wasi Lodge","descripcion":"Departure from Cusco at 6:00 AM. We drive through the stunning cloud forest, stopping at viewpoints along the way. Arrive at Machu Wasi Lodge in the afternoon. Enjoy a welcome dinner and night walk spotting nocturnal wildlife."},{"dia":2,"titulo":"River Safari & Wildlife Walks","descripcion":"Early morning boat safari on the river searching for caimans, capybaras, and birds. Afternoon jungle walks on forest trails with our expert local guide. Evening optional fishing."},{"dia":3,"titulo":"Morning Wildlife ÔåÆ Return to Cusco","descripcion":"Final morning birdwatching session. After breakfast, we begin the return journey to Cusco, arriving in the late afternoon."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('4-day-wildlife-quest-machu-wasi', '4-day-wildlife-quest-machu-wasi', '4-Day Wildlife Quest ÔÇô Machu Wasi', 'wildlife', 'activo', 4, 3, 580, 'USD', 2, 8, 'F├ícil', 'Todo el a├▒o', 'Cuatro d├¡as para explorar la selva amaz├│nica en profundidad desde Machu Wasi. Ver ca├¡manes, capybaras, monos y aves de la Amazon├¡a.', 'El tour de 4 d├¡as a Machu Wasi ofrece m├ís tiempo en la selva para aumentar las probabilidades de avistar vida silvestre. Con tres noches en el lodge, tenemos tiempo para caminatas de d├¡a y de noche, safaris en bote y actividades de kayak.', 'assets/img/hero.png', '4-Day Wildlife Quest at Machu Wasi ÔÇô Manu National Park', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest ÔåÆ Machu Wasi Lodge","descripcion":"Departure from Cusco at 6:00 AM. Drive through the cloud forest with stops at scenic viewpoints. Arrive at the lodge in the afternoon for welcome dinner and night walk."},{"dia":2,"titulo":"River Safari & Jungle Walks","descripcion":"Full day of wildlife activities: morning boat safari, afternoon jungle trails, evening optional piranha fishing."},{"dia":3,"titulo":"Deep Jungle Exploration","descripcion":"Longer hike into the forest to discover hidden oxbow lakes. Kayaking on the river. Sunset watching from the observation platform."},{"dia":4,"titulo":"Morning Birds ÔåÆ Return to Cusco","descripcion":"Final birdwatching session at dawn. Breakfast and return journey to Cusco arriving late afternoon."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('4-day-wildlife-quest-nuevo-eden', '4-day-wildlife-quest-nuevo-eden', '4-Day Wildlife Quest ÔÇô Nuevo Eden', 'wildlife', 'activo', 4, 3, 560, 'USD', 2, 8, 'F├ícil', 'Todo el a├▒o', 'Tour de vida silvestre de 4 d├¡as desde el pueblo de Nuevo Eden, hogar de nuestra familia fundadora. Una experiencia profundamente local y aut├®ntica.', 'Nuevo Eden es el pueblo donde creci├│ Mois├®s, co-fundador de Manu Jungle Forever. Este tour ofrece la experiencia m├ís aut├®ntica con acceso a nuestros propios senderos privados y lodge familiar.', 'assets/img/hero.png', 'Wildlife Quest at Nuevo Eden ÔÇô Manu National Park', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Nuevo Eden Lodge","descripcion":"Early morning departure from Cusco. Scenic drive through the Andes and cloud forest. Arrive at Nuevo Eden and begin with an evening boat trip."},{"dia":2,"titulo":"Wildlife Safari Day","descripcion":"Full day wildlife activities: morning boat safari on the Madre de Dios river, afternoon jungle walks, night walk."},{"dia":3,"titulo":"Village Life & Nature","descripcion":"Visit the community of Nuevo Eden, learn about local traditions, afternoon kayak session, evening wildlife spotting."},{"dia":4,"titulo":"Dawn Birds ÔåÆ Cusco","descripcion":"Sunrise birdwatching, breakfast, return drive to Cusco."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('5-day-wildlife-quest-nuevo-eden', '5-day-wildlife-quest-nuevo-eden', '5-Day Wildlife Quest ÔÇô Nuevo Eden', 'wildlife', 'activo', 5, 4, 680, 'USD', 2, 8, 'Moderado', 'Todo el a├▒o', 'Cinco d├¡as de inmersi├│n total en la selva amaz├│nica desde Nuevo Eden con mayores probabilidades de avistar fauna ex├│tica.', 'El tour de 5 d├¡as a Nuevo Eden es nuestra opci├│n m├ís popular para quienes quieren m├íxima exposici├│n a la vida silvestre con comodidad. Con cuatro noches, exploramos la selva, los r├¡os y el bosque nuboso en toda su diversidad.', 'assets/img/hero.png', '5-Day Wildlife Quest at Nuevo Eden', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Nuevo Eden","descripcion":"Departure from Cusco, cloud forest drive, evening arrival and welcome dinner."},{"dia":2,"titulo":"River Safari & Jungle Walks","descripcion":"Full day of wildlife activities on the river and trails."},{"dia":3,"titulo":"Oxbow Lake & Deep Forest","descripcion":"Boat trip to a hidden oxbow lake. Afternoon hiking in primary rainforest."},{"dia":4,"titulo":"Fishing, Kayak & Night Walk","descripcion":"Fishing for piranhas, kayak session, traditional piranha fishing dinner, night wildlife walk."},{"dia":5,"titulo":"Dawn Walk ÔåÆ Return to Cusco","descripcion":"Early morning bird walk, breakfast, return to Cusco."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('6-day-wildlife-quest-blanquillo', '6-day-wildlife-quest-blanquillo', '6-Day Wildlife Quest ÔÇô Blanquillo', 'wildlife', 'activo', 6, 5, 890, 'USD', 2, 8, 'Moderado', 'Todo el a├▒o', 'El tour de 6 d├¡as a Blanquillo incluye la visita al famoso comedero de arcilla de guacamayos ÔÇö uno de los espect├ículos de vida silvestre m├ís impresionantes del Per├║.', 'Blanquillo es famoso por su colpa de guacamayos, donde cientos de guacamayos de colores llegan cada ma├▒ana al amanecer. Este tour de 6 d├¡as incluye esta experiencia ├║nica m├ís 5 noches de exploraci├│n intensiva de la selva amaz├│nica.', 'assets/img/hero.png', '6-Day Wildlife Quest ÔÇô Blanquillo Macaw Clay Lick', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest ÔåÆ Nuevo Eden","descripcion":"Early departure, scenic cloud forest drive, afternoon arrival."},{"dia":2,"titulo":"River Wildlife Safari","descripcion":"Full day boat safaris searching for caimans, giant otters and river wildlife."},{"dia":3,"titulo":"Blanquillo Macaw Clay Lick ÔÇô Dawn","descripcion":"Pre-dawn boat journey to the famous Blanquillo clay lick. Watch hundreds of colorful macaws gather at sunrise."},{"dia":4,"titulo":"Deep Jungle Expedition","descripcion":"Trek into primary rainforest. Night walk to spot nocturnal wildlife."},{"dia":5,"titulo":"Oxbow Lake & Fishing","descripcion":"Visit a remote oxbow lake, piranha fishing, community visit in Nuevo Eden."},{"dia":6,"titulo":"Sunrise Birds ÔåÆ Return to Cusco","descripcion":"Final morning birdwatching, breakfast, return to Cusco."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('6-day-wildlife-quest-reserved-zone', '6-day-wildlife-quest-reserved-zone', 'Manu Reserved Zone ÔÇô 6 Days', 'wildlife', 'activo', 6, 5, 1200, 'USD', 2, 8, 'Moderado', 'Abril a Noviembre', 'El tour m├ís exclusivo de Manu Jungle Forever: acceso a la Zona Reservada del Manu donde la vida silvestre es m├ís abundante y el h├íbitat est├í pristino.', 'La Zona Reservada del Parque Nacional Manu es una de las ├íreas m├ís biodiversas del planeta. Este tour de 6 d├¡as penetra hasta el coraz├│n de la reserva con permisos especiales para brindar el m├íximo avistamiento de fauna.', 'assets/img/hero.png', 'Manu National Park Reserved Zone Tour', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest","descripcion":"Early departure, overnight in cloud forest lodge."},{"dia":2,"titulo":"Cloud Forest ÔåÆ Manu Zone","descripcion":"Continue journey into the Manu buffer zone. First wildlife sightings."},{"dia":3,"titulo":"Enter the Reserved Zone","descripcion":"Enter the restricted reserved zone. Exceptional wildlife viewing on the river."},{"dia":4,"titulo":"Deep Manu Exploration","descripcion":"Full day in the reserved zone: trails, river safaris, macaw lick."},{"dia":5,"titulo":"Return Journey Begins","descripcion":"Start return, overnight in buffer zone."},{"dia":6,"titulo":"Return to Cusco","descripcion":"Complete return to Cusco."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('8-day-wildlife-photography-tour', '8-day-wildlife-photography-tour', 'Wildlife Photography Tour ÔÇô 8 Days', 'wildlife', 'activo', 8, 7, 1450, 'USD', 2, 6, 'Moderado', 'Todo el a├▒o', 'Dise├▒ado para fot├│grafos de vida silvestre: 8 d├¡as en los mejores puntos fotogr├íficos de la Amazon├¡a peruana con gu├¡as especializados.', 'Este tour de 8 d├¡as est├í dise├▒ado espec├¡ficamente para fot├│grafos de naturaleza. Visitamos los mejores spots de fotograf├¡a de vida silvestre en el Manu: la colpa de guacamayos de Blanquillo, latrinas de mam├¡feros, lagos de cochas y mucho m├ís.', 'assets/img/hero.png', 'Wildlife Photography Tour ÔÇô Manu National Park', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest","descripcion":"Departure and first stop for cloud forest bird photography at dawn."},{"dia":2,"titulo":"Cloud Forest Photography","descripcion":"Full day shooting cloud forest wildlife: cock-of-the-rock, hummingbirds, orchids."},{"dia":3,"titulo":"Descent to Lowland Rainforest","descripcion":"Journey to the lowlands. River photography afternoon."},{"dia":4,"titulo":"Blanquillo Macaw Lick","descripcion":"Dawn at the famous macaw clay lick. Hundreds of macaws."},{"dia":5,"titulo":"Cocha Wildlife Photography","descripcion":"Kayak to a remote oxbow lake to photograph giant otters and wading birds."},{"dia":6,"titulo":"Night Photography & Mammals","descripcion":"Specialist night photography session for nocturnal mammals and insects."},{"dia":7,"titulo":"River Banks & Caiman Photography","descripcion":"Early morning boat safari for caiman photography. Afternoon river birds."},{"dia":8,"titulo":"Return to Cusco","descripcion":"Final morning shoot, return to Cusco."}]', '["Van privada","Bote"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('rainforest-road-trip', 'rainforest-road-trip-from-cusco', 'Rainforest Road Trip Overview', 'roadtrip', 'activo', 4, 3, 380, 'USD', 1, 3, 'F├ícil', 'Abril a Noviembre (no disponible diciembre-marzo)', 'El tour m├ís aut├®ntico de la Amazon├¡a peruana: un viaje en 4x4 por las aldeas y paisajes del camino de Cusco a Manu. Presupuesto amigable.', 'El Rainforest Road Trip es nuestra opci├│n m├ís econ├│mica y aut├®ntica. Viajamos en 4x4 privado por el sinuoso camino de Cusco a Manu, parando en aldeas locales, probando comida tradicional y viendo fauna en el bosque nuboso.', 'assets/img/hero.png', 'Rainforest Road Trip from Cusco to Manu', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest Villages","descripcion":"4x4 departure, visit local villages in the cloud forest."},{"dia":2,"titulo":"Deeper into the Jungle","descripcion":"Continue towards the rainforest. Swimming in natural pools. Wildlife spotting."},{"dia":3,"titulo":"Jungle Exploration","descripcion":"Walks in the lowland forest. Local food experience."},{"dia":4,"titulo":"Return to Cusco","descripcion":"Return drive with stops along the way."}]', '["4x4 privado"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('2-day-rainforest-road-trip', '2-day-rainforest-road-trip', '2-Day Road Trip', 'roadtrip', 'activo', 2, 1, 260, 'USD', 1, 4, 'F├ícil', 'Abril a Noviembre', 'Un viaje corto en 4x4 por la ruta de los Andes hacia el bosque nuboso y la entrada a la selva del Manu.', 'Esc├ípate 2 d├¡as a la selva en una emocionante traves├¡a 4x4 desde Cusco. Ideal para quienes disponen de poco tiempo pero quieren cruzar los Andes y sentir la magia de la Amazon├¡a.', 'assets/img/hero.png', '2-Day Rainforest Road Trip ÔÇô Manu National Park', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Cloud Forest Villages","descripcion":"Salida en 4x4 desde Cusco atravesando los Andes hacia el bosque nuboso. Observaci├│n de aves y estad├¡a en lodge local."},{"dia":2,"titulo":"Jungle Exploration ÔåÆ Retorno a Cusco","descripcion":"Caminata matutina por senderos naturales y viaje de retorno a Cusco por la tarde."}]', '["4x4 privado"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('5-day-rainforest-road-trip', '5-day-rainforest-road-trip', '5-Day Road Trip', 'roadtrip', 'activo', 5, 4, 480, 'USD', 1, 4, 'F├ícil', 'Abril a Noviembre', 'Traves├¡a completa de 5 d├¡as en 4x4 recorriendo los valles andinos, el bosque nuboso y los r├¡os de la selva baja del Manu.', 'Una aventura ├®pica por tierra y r├¡o recorriendo las comunidades y reservas naturales entre Cusco y el Manu.', 'assets/img/hero.png', '5-Day Rainforest Road Trip ÔÇô Manu National Park', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Paucartambo ÔåÆ Bosque Nuboso","descripcion":"Ruta panor├ímica andina con paradas fotogr├íficas y avistamiento del Gallito de las Rocas."},{"dia":2,"titulo":"Descenso a la Selva Baja","descripcion":"Exploraci├│n de cascadas naturales, comunidades locales y navegaci├│n inicial."},{"dia":3,"titulo":"Inmersi├│n en Selva Primaria","descripcion":"Caminatas diurnas y nocturnas para avistar monos, caimanes y vida silvestre."},{"dia":4,"titulo":"R├¡o y Cultura Local","descripcion":"Safari fluvial, pesca tradicional y vivencia comunitaria."},{"dia":5,"titulo":"Retorno a Cusco","descripcion":"Desayuno y retorno en 4x4 hacia la ciudad de Cusco."}]', '["4x4 privado"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('5-day-amazon-expedition', '5-day-amazon-expedition', '5-Day Amazon Expedition', 'expedition', 'activo', 5, 4, 1200, 'USD', 2, 8, 'Moderado', 'Mayo a Octubre', 'Para aventureros serios: 5 d├¡as de expedici├│n profunda en la selva, acampando, pescando, aprendiendo supervivencia y alej├índose de la civilizaci├│n.', 'La Expedici├│n Amaz├│nica de 5 d├¡as es para quienes quieren realmente sumergirse en la selva. Dormimos en campamentos, pescamos piranhas, aprendemos t├®cnicas de supervivencia y exploramos ├íreas remotas que los tours convencionales no alcanzan.', '/media/1786591103305-pteronura-brasiliensis-zoo-brasilia-01.jpg', '5-Day Amazon Expedition from Cusco', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Jungle Base Camp","descripcion":"Travel to the jungle and set up base camp."},{"dia":2,"titulo":"River Expedition","descripcion":"Full day boat expedition deep into the Amazon. Fishing and wildlife."},{"dia":3,"titulo":"Survival Skills","descripcion":"Learn to build shelters, find food, navigate without technology."},{"dia":4,"titulo":"Deep Forest Trek","descripcion":"Long day hike in rubber boots into primary rainforest. Night camping."},{"dia":5,"titulo":"Return to Cusco","descripcion":"Pack up camp and return to Cusco."}]', '["Van privada","Bote","Senderismo"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('6-day-amazon-expedition', '6-day-amazon-expedition', '6-Day Amazon Expedition', 'expedition', 'activo', 6, 5, 860, 'USD', 2, 8, 'Dif├¡cil', 'Mayo a Octubre', 'La expedici├│n m├ís completa: 6 d├¡as de aventura profunda en la selva amaz├│nica para viajeros en busca de una experiencia realmente salvaje.', 'La Expedici├│n Amaz├│nica de 6 d├¡as agrega un d├¡a completo de exploraci├│n comparado con la versi├│n de 5 d├¡as, permitiendo llegar a ├íreas a├║n m├ís remotas del Parque Nacional Manu.', 'assets/img/hero.png', '6-Day Amazon Expedition from Cusco', '[]', '[{"dia":1,"titulo":"Cusco ÔåÆ Base Camp","descripcion":"Travel and setup."},{"dia":2,"titulo":"River Expedition","descripcion":"Deep river exploration."},{"dia":3,"titulo":"Survival Day 1","descripcion":"Survival skills training in the jungle."},{"dia":4,"titulo":"Remote Forest Trek","descripcion":"Long trek into remote primary forest."},{"dia":5,"titulo":"Deep Amazon Camp","descripcion":"Final night deep in the jungle."},{"dia":6,"titulo":"Return to Cusco","descripcion":"Return journey."}]', '["Van privada","Bote","Senderismo"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO tours (id, slug, nombre, categoria, estado, duracion_dias, duracion_noches, precio_desde, moneda, capacidad_min, capacidad_max, dificultad, temporada, descripcion_corta, descripcion_larga, imagen_hero, imagen_alt, galeria_json, itinerario_json, transporte_json, created_at, updated_at) VALUES ('7-day-deep-amazon-wildlife-quest', '7-day-deep-amazon-wildlife-quest', '7-Day Deep Amazon Wildlife Quest', 'wildlife', 'activo', 7, 6, 1300, 'USD', 2, 8, 'F├ícil', 'Mayo - Noviembre (Temporada Seca)', 'An in-depth 7-day wildlife expedition deep into the pristine primary rainforest of Manu National Park, searching for jaguars, tapirs, giant river otters, and macaws.', 'Our 7-Day Deep Amazon Wildlife Quest takes you deep into the heart of the Manu Biosphere Reserve. Journey through the mystical cloud forest of the Andes down to the Amazonian lowlands. Navigate winding rivers, explore hidden oxbow lakes (cochas) on silent catamarans, visit world-renowned macaw clay licks (colpas), and spend nights listening to the symphony of the jungle at our comfortable rainforest lodges with professional bilingual naturalist guides.', '/media/1786591103305-pteronura-brasiliensis-zoo-brasilia-01.jpg', '7-Day Deep Amazon Wildlife Quest in Manu National Park', '[{"url":"assets/media_to_upload/photos/placeholder.jpg","alt":"Amazon Wildlife Expedition"}]', '[{"dia":1,"titulo":"Cusco ÔåÆ Andes Mountain Pass ÔåÆ Cloud Forest Lodge","descripcion":"Early morning pick-up from your hotel in Cusco (5:30 AM). Scenic drive over the Andes with stops at pre-Inca Ninamarca chullpas and the folkloric town of Paucartambo. Descend into the lush Cloud Forest of Manu to spot the Andean Cock-of-the-Rock (Peru''s national bird), woolly monkeys, and orchids. Night walk near the lodge."},{"dia":2,"titulo":"Cloud Forest ÔåÆ Atalaya Port ÔåÆ Rainforest Lodge","descripcion":"Morning birdwatching walk. Continue driving to Atalaya river port, transition to motorized dugout canoe, and navigate down the Madre de Dios River. Spotting herons, kingfishers, and sunbathing caimans. Afternoon trek along primary forest trails with introduction to medicinal plants."},{"dia":3,"titulo":"Machu Wasi Oxbow Lake & Mammal Clay Lick","descripcion":"Dawn excursion to Machu Wasi Lake on traditional balsa rafts to observe prehistoric hoatzin birds, horned screamers, capybaras, and monkeys. In the evening, visit a natural tapir clay lick platform for a night vigil."},{"dia":4,"titulo":"Deep River Navigation ÔåÆ Blanquillo Biological Station","descripcion":"Embark on an extended boat expedition further downriver into deeper rainforest sectors. High probability of encountering river wildlife such as side-necked turtles, capybara families, and elusive jaguars on the beaches. Settle into Blanquillo Lodge."},{"dia":5,"titulo":"Blanquillo Macaw Clay Lick & Cocha Blanco Lake","descripcion":"Early 5:00 AM departure to the hidden macaw clay lick blind. Witness hundreds of red-and-green macaws, parrots, and parakeets gathering in a spectacle of color. Afternoon exploration of Cocha Blanco to search for the resident family of Giant River Otters (*Pteronura brasiliensis*)."},{"dia":6,"titulo":"Canopy Tower Observation & Primary Rainforest Treks","descripcion":"Climb the 42-meter canopy observation tower for breathtaking panoramic views across the Amazon treetops, perfect for toucans, cotingas, and raptors. Afternoon deep forest exploration focusing on ancient giant ceiba trees and diverse monkey troops."},{"dia":7,"titulo":"Upriver Return Boat Trip ÔåÆ Cusco","descripcion":"Early morning upriver boat ride back to Atalaya port. Transfer to our private van for the scenic return journey through the Andes, arriving in Cusco around 7:00 PM."}]', '["Van privada","Bote a motor"]', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');

