INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_discovering_wildlife_manu_national_park', 'discovering-wildlife-manu-national-park', 'Discovering the Untamed Wildlife of Manu National Park', 'Manu Jungle Forever', '2026-08-16', 'Wildlife', 'Explore the incredible biodiversity of Manu National Park. From elusive jaguars to vibrant macaws, discover why this untouched Amazonian paradise is a must-visit for wildlife enthusiasts.', '', '/media/1787015599134-gayulo-animals-3524518.jpg', 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_amazon_rainforest_tour_to_manu_national_park_from_cusco', 'amazon-rainforest-tour-to-manu-national-park-from-cusco', 'Amazon Rainforest Tour to Manu National Park from Cusco', 'Manu Jungle Forever', '2026-05-15', 'Wildlife', 'Wildlife of Manu National Park ÔÇö discover the incredible biodiversity of the Peruvian Amazon on a guided tour from Cusco.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_climate_change_manu_national_park_peru', 'climate-change-manu-national-park-peru', 'Climate Change in Manu National Park: Protecting One of the World''s Most Biodiverse Places', 'Manu Jungle Forever', '2026-03-05', 'Conservation', 'The Manu National Park is one of the most biodiverse places on Earth. Here''s how climate change threatens this paradise and what we can do.', '', '/media/1786477360363-jordy.jpg', 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_everything_you_need_to_know_before_visiting_machu_picchu', 'everything-you-need-to-know-before-visiting-machu-picchu', 'Everything You Need to Know Before Visiting Machu Picchu', 'Manu Jungle Forever', '2023-11-16', 'Travel Tips', 'Machu Picchu tours from Cusco are on the bucket list of many travelers, and it''s no surprise. Here''s everything you need to know before visiting.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_five_reasons_to_visit_manu_national_park', 'five-reasons-to-visit-manu-national-park', 'Five Reasons to Visit Manu National Park', 'Manu Jungle Forever', '2022-07-10', 'Manu Park', 'Discover the top five reasons why Manu National Park should be at the top of your Peru bucket list.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_how_tourism_helps_the_manu_national_park', 'how-tourism-helps-the-manu-national-park', 'How Tourism Helps the Manu National Park', 'Manu Jungle Forever', '2024-06-22', 'Sustainability', 'Nestled in southeastern Peru, the Manu National Park is a remarkable UNESCO World Heritage Site. Spanning 1.5 million hectares, it''s home to...', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_manu_national_park_in_8_days_complete_travel_guide_to_the_peruvian_amazon', 'manu-national-park-in-8-days-complete-travel-guide-to-the-peruvian-amazon', 'Manu National Park in 8 Days: Complete Travel Guide to the Peruvian Amazon', 'Manu Jungle Forever', '2026-04-06', 'Manu Park', 'A complete travel guide to Manu National Park in 8 days ÔÇö discover the best wildlife, activities and insider tips for the Peruvian Amazon.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_meet_jordy_our_expert_guide', 'meet-jordy-our-expert-guide', 'Meet Jordy: Our Expert Amazon Guide', 'Manu Jungle Forever', '2026-08-11', 'Our Team', 'Get to know Jordy, our passionate and experienced guide who will take you deep into the heart of the Manu National Park.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_packing_list_for_your_trip_to_the_peruvian_amazon', 'packing-list-for-your-trip-to-the-peruvian-amazon', 'Packing List for Your Trip to the Peruvian Jungle', 'Manu Jungle Forever', '2022-12-31', 'Travel Tips', 'If you have already decided that for your next vacation you will take a trip to the Peruvian Amazon, here''s the complete packing list.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_peru_travel_tips', 'peru-travel-tips', 'Peru Travel Tips', 'Manu Jungle Forever', '2023-09-20', 'Travel Tips', 'Peru is a country of stunning landscapes, rich history, and diverse cultures. Essential tips to make the most of your Peruvian adventure.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_sustainable_tourism_in_the_manu_biosphere_reserve_conservation_through_private_agricultural_lands', 'sustainable-tourism-in-the-manu-biosphere-reserve-conservation-through-private-agricultural-lands', 'Sustainable Tourism in the Manu Biosphere Reserve: Conservation Through Private Agricultural Lands', 'Manu Jungle Forever', '2026-05-12', 'Sustainability', 'Sustainable tourism in the Manu Biosphere Reserve promoting conservation, biodiversity, and eco-friendly travel in the Peruvian Amazon.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_what_to_see_when_traveling_to_the_peruvian_amazon_complete_guide_2026', 'what-to-see-when-traveling-to-the-peruvian-amazon-complete-guide-2026', 'What you will See When Traveling to the Peruvian Amazon: Complete Guide 2026', 'Manu Jungle Forever', '2026-03-23', 'Wildlife', 'Introduction: The Amazon rainforest in Peru is one of the most biodiverse places on Earth. Here''s everything you will see on your trip.', '', NULL, 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO blog_posts (id, slug, titulo, autor, fecha, categoria, extracto, contenido, imagen_hero, estado, created_at, updated_at) VALUES ('post_why_visit_the_manu_national_park', 'why-visit-the-manu-national-park', 'Why Visit the Manu National Park?', 'Manu Jungle Forever', '2021-03-15', 'Manu Park', 'Manu National Park is one of the world''s most biodiverse places. Find out why it should be your next adventure destination.', '', '/media/1786477360363-jordy.jpg', 'publicado', '2026-08-22T23:46:25.186Z', '2026-08-22T23:46:25.186Z');

-- testimonials
INSERT OR REPLACE INTO testimonials (id, nombre, pais, tour_nombre, rating, comentario, foto, fecha, origen, estado, created_at) VALUES ('1', 'James W.', 'United Kingdom', 'Amazon Expedition', 4, 'An absolutely incredible experience. The guides were deeply knowledgeable and passionate about the rainforest. We saw giant river otters, caimans, and countless macaws. The lodge was rustic but perfectly comfortable. Highly recommend this local agency!', '/media/1786477360363-jordy.jpg', '2026-08-22', 'tripadvisor', 'publicado', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO testimonials (id, nombre, pais, tour_nombre, rating, comentario, foto, fecha, origen, estado, created_at) VALUES ('2', 'Sarah T.', 'United States', 'Wildlife Quest', 5, 'The highlight of our Peru trip! Going deep into the Amazon with indigenous guides made all the difference. We felt completely safe while being totally immersed in nature. The night walks through the jungle were mind-blowing. Thank you for everything!', '/media/1787335803567-10290631_478172738980891_705162467606874687_n.jpg', '2025', 'google', 'publicado', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO testimonials (id, nombre, pais, tour_nombre, rating, comentario, foto, fecha, origen, estado, created_at) VALUES ('3', 'Matteo C.', 'Italy', 'Amazon Adventure', 5, 'If you want to see untouched wilderness, this is the company to book with. No crowded tourist traps, just pure Amazon. The food was surprisingly fantastic, and seeing a jaguar resting on the riverbank is a memory I will cherish forever.', NULL, '2025', 'tripadvisor', 'publicado', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO testimonials (id, nombre, pais, tour_nombre, rating, comentario, foto, fecha, origen, estado, created_at) VALUES ('4', 'Elena R.', 'Spain', 'Manu Reserved Zone', 5, 'Una experiencia inolvidable. Ver a los guacamayos en la colpa de arcilla y navegar por el r├¡o Manu fue m├ígico. El equipo de Manu Jungle Forever nos cuid├│ en todo momento con una calidez excepcional.', NULL, '2025', 'google', 'publicado', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO testimonials (id, nombre, pais, tour_nombre, rating, comentario, foto, fecha, origen, estado, created_at) VALUES ('5', 'Lucas M.', 'Germany', 'Wildlife Photography', 5, 'As a wildlife photographer, this was paradise. The guides knew exactly where to spot monkeys, toucans and river otters. Flawless organization from start to finish.', NULL, '2025', 'web', 'publicado', '2026-08-22T23:46:25.186Z');

