INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('about', '{"hero_image":"/media/1786897485978-133629791959893989.jpg","hero_image_alt":"Manu Jungle Forever ÔÇô Familia y Gu├¡as","titulo_pagina":"About Manu Jungle Forever","subtitulo_pagina":"A family-run eco-tourism company born from the rainforest of Nuevo Eden, Peru.","historia":{"eyebrow":"Our Story","titulo":"Born in the Jungle","paragrafos":["Dear Curious Traveler,","Our team at Manu Jungle Forever is excited to share your jungle travel with you. We are a family business, working with local professionals to create an unforgettable experience.","The Llaqui family will welcome you and be your guides. Jordy has been a professional tour guide in the Amazon jungle for many years, and with GloriaÔÇÖs dedication to conservation, they operate this project together. They have created these tours and jungle adventures to provide a unique experience in the Manu National Park.","When Gloria joined the project, she brought her deep knowledge of the region to every itinerary. The Llaqui family were welcoming and generous with their time and hospitality. They organized fishing trips, ate fresh local food, swam in the river, and more.  Whereas her trip as a tourist was strictly nature-focused, this trip was a complete immersion into a totally different life. Yet, she was in the same little slice of jungle for both.","Manu Jungle Forever celebrates the whole jungle: the magnificent nature, and the local life. As a traveler, you can choose your priority and focus. We offer 3 types of guided tours that range from very nature-based to very culture-based. Or, you can customize your own adventure using our beautiful jungle bungalow as your base.","LetÔÇÖs meet our team of jungle experts and family members that youÔÇÖll meet along the way."],"imagen":"/media/usuarios/kemmesik-gmail-com/avatar_1787257830305.jpg","imagen_alt":"Jordy Leonidas ÔÇô Founder of Manu Jungle Forever"},"mision":{"eyebrow":"Our Mission","titulo":"Tourism as Conservation","texto":"We believe that responsible, community-based ecotourism is the most powerful tool available to protect the Amazon rainforest. By making the jungle economically valuable to local communities through tourism, we create a sustainable alternative to logging and destructive agriculture. Our mission is to show visitors the extraordinary beauty of the Manu National Park while ensuring that every visit leaves a positive impact on the environment and local people.","valores":[{"icono":"fas fa-home","titulo":"Community First","texto":"100% of our staff are local community members. Your tour dollars go directly into the village economy."},{"icono":"fas fa-leaf","titulo":"Environmental Stewardship","texto":"We practice strict Leave No Trace principles and actively participate in reforestation and wildlife monitoring programs."},{"icono":"fas fa-users","titulo":"Small Groups Only","texto":"We limit group sizes to a maximum of 8 travelers to minimize our environmental footprint and maximize personal attention."},{"icono":"fas fa-shield-alt","titulo":"Safety & Professionalism","texto":"All guides are certified in wilderness first aid. We maintain the highest safety standards without compromising adventure."}]},"equipo":[{"nombre":"Moises Ara├▒a","cargo":"Co-Founder & Head Guide","bio":"Born and raised in Nuevo Eden, Moises has been guiding in the Manu National Park for over 15 years. His encyclopedic knowledge of Amazonian wildlife and his warm, engaging personality make every tour unforgettable.","foto":"assets/media_to_upload/photos/placeholder.jpg","especialidad":"Wildlife identification, river navigation, jungle survival"},{"nombre":"Rosa Ara├▒a","cargo":"Co-Founder & Operations Manager","bio":"Rosa manages the day-to-day operations of Manu Jungle Forever and oversees the kitchen team, ensuring that every meal served reflects the authentic flavors of the Peruvian Amazon.","foto":"assets/media_to_upload/photos/placeholder.jpg","especialidad":"Operations, logistics, Amazonian cuisine"},{"nombre":"Carlos Ara├▒a","cargo":"Senior Wildlife Guide","bio":"Carlos is Moises''s brother and has a particular passion for herpetology ÔÇö snakes, frogs, and lizards of the Amazon. He is also an expert birder with knowledge of over 800 species of Manu birds.","foto":"assets/media_to_upload/photos/placeholder.jpg","especialidad":"Herpetology, birding, jungle trekking"}],"numeros":[{"valor":"10+","etiqueta":"Years in Business"},{"valor":"500+","etiqueta":"Travelers Guided"},{"valor":"12","etiqueta":"Local Staff Members"},{"valor":"4.9Ôÿà","etiqueta":"Average Rating"}]}', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('home', '{"hero":{"location_tag":"Cusco, Peru ┬À Manu National Park","title":"What Will","title_emphasis":"Discover?","subtitle":"Visit Manu National Park from Cusco ÔÇö guided jungle tours deep into the Peruvian Amazon. Local. Wild. Authentic.","video_id":"mwFesIvZ5Zc","video_start":4,"video_end":56,"cta_primary":"Book a Tour","cta_tours":"See All Tours","cta_about":"About Us"},"stats":[{"value":500,"suffix":"+","label":"Travelers Guided","type":"counter"},{"value":10,"suffix":"+","label":"Years Experience","type":"counter"},{"value":12,"suffix":"","label":"Tour Options","type":"counter"},{"value":"4.9Ôÿà","label":"Average Rating","type":"static"}],"guided_tours":{"title":"Guided Tours","subtitle":"Curated Jungle Expeditions","description":"Our itineraries are meticulously designed to cater to true nature enthusiasts. From deep-forest survival treks for the intrepid explorer, to focused wildlife spotting cruises along the riverbanks, our routes guarantee a transformative encounter with the wild.","categories":[{"id":"cat-1","categoria":"wildlife","disponible":true,"badge_texto":"Available Now","titulo":"Jungle Wildlife Tour","duracion":"3, 4, 5, 6 or 8 Days","pasajeros":"2ÔÇô8 Passengers","transporte":"Van & Boat","descripcion":"Manu National Park tours from Cusco where you travel by van through the cloud forest, then search for Peruvian Amazon animals by boat. See caimans, macaws, capybaras, and the elusive jaguar. Beautiful scenery, local food, incredible nature ÔÇö appropriate for all travelers.","boton_texto":"Explore This Tour","enlace":"guided-tours/index.html#wildlife","imagen":"/media/1787018009678-willife.jpeg","imagen_alt":"Jungle Wildlife Tour"},{"id":"cat-2","categoria":"roadtrip","disponible":true,"badge_texto":"Available Now","titulo":"Rainforest Road Trip","duracion":"4 or 5 Days","pasajeros":"1ÔÇô3 Passengers","transporte":"Private 4├ù4","descripcion":"Our most authentic Peru Amazon tour takes you through villages along the winding road from Cusco to Manu. Spot animals in the cloud forest, taste local flavors, and visit hidden gems.","boton_texto":"View Details","enlace":"guided-tours/index.html#rainforest","imagen":"/media/1787019022145-mohamed-hassan-sunset-3754082.jpg","imagen_alt":"Rainforest Road Trip"},{"id":"cat-3","categoria":"expedition","disponible":true,"badge_texto":"Available Now","titulo":"Manu Expedition","duracion":"5 or 6 Days","pasajeros":"2ÔÇô8 Passengers","transporte":"Van, Boat & Hiking","descripcion":"Perfect for adventurous nature lovers ÔÇö this expedition takes you deep into the forest. Camp, fish, hike, and learn survival skills.","boton_texto":"View Details","enlace":"guided-tours/index.html#amazon","imagen":"/media/usuarios/kemmesik-gmail-com/avatar_1787257830305.jpg","imagen_alt":"Manu Expedition"}]},"about_section":{"eyebrow":"Why Choose Us","title":"Visit Manu National Park with a Local Company","paragraphs":[{"text":"Going to the Amazon rainforest is a dream for many travelers planning their South American adventure. If you''re looking for an amazing jungle trip near Cusco, Peru, you''re in the right place."},{"text":"The Manu National Park is accessible by road and river from Cusco, located on the Madre de Dios and Manu rivers ÔÇö tributaries to the Amazon itself. Our founder grew up in the small village of Nuevo Eden that we use as our base; the rainforest is his home."},{"text":"We offer multi-day guided small-group tours and can also organize independent trips to Manu. All our jungle tours can be added onto your Cusco trip while visiting Machu Picchu and the Sacred Valley. You will get a taste of local life and opportunities to see amazing creatures in their natural habitat."}],"chips":["Small Groups (2ÔÇô8)","Born-Local Guides","All-Inclusive Tours","Flexible Departures","Guided or Independent"],"image":"/media/1787016658101-puesta-de-sol.jpeg","image_alt":"Wildlife quest at Machu Wasi ÔÇô Manu National Park","cta_text":"Our Full Story","cta_url":"about/index.html"},"unique_section":{"title":"WHAT MAKES US UNIQUE?","text":"Born in the heart of Manu, we are a proudly local, family-owned company. Our lodge and trail network in Nuevo Ed├®n are not just a tourist destination, but the childhood home of our co-founder, Jordy. We firmly believe that ecotourism is the strongest and most sustainable shield to preserve the Amazon. Through our work, we aim to uplift the community and protect the species that inhabit the jungle. Without responsible tourism, this paradise would face the constant threat of deforestation and destructive agriculture. We are driven by a deep passion to share the culture, biodiversity, and spirit of Manu National Park with you.","image":"/media/1787017112075-eden.jpeg","image_alt":"Manu Jungle Forever Family and Guides","eyebrow":"A Legacy of Conservation"},"wildlife_section":{"eyebrow":"Biodiversity","title":"Wildlife in the Peruvian Rainforest","text":"The Manu National Park is the best place to see wildlife in Peru ÔÇö you will always encounter animals in their natural habitats, surrounded by a complex ecosystem. When we visit the Amazon rainforest, we explore trails looking for monkeys, macaws, insects, snakes, and more. On the river banks we search for capybaras, turtles, caimans, and even the elusive jaguar.","image":"/media/1787015599134-gayulo-animals-3524518.jpg","image_alt":"Manu National Park wildlife - Jaguar","animals":[{"emoji":"­ƒÉå","name":"Jaguar"},{"emoji":"­ƒª£","name":"Macaws"},{"emoji":"­ƒÉè","name":"Caimans"},{"emoji":"­ƒÉÆ","name":"Monkeys"},{"emoji":"­ƒªª","name":"Giant Otters"},{"emoji":"­ƒÉó","name":"River Turtles"},{"emoji":"­ƒª½","name":"Capybaras"},{"emoji":"­ƒÉì","name":"Anaconda"},{"emoji":"­ƒªï","name":"Butterflies"},{"emoji":"­ƒÉª","name":"Cock-of-the-Rock"}]},"cta_section":{"eyebrow":"Ready to Explore?","title":"Let''s Go to the Jungle. Plan Your Trip Today.","text":"Let''s Go to the Jungle. Plan Your Trip Today.","image":"/media/1787018890459-letsgo.jpg","btn_text":"Book a Tour","btn_url":"contact/index.html"},"pillars_section":{"eyebrow":"Our Values","title":"Our Pillars","pillars":[{"icon":"fas fa-home","title":"Family Business Supporting Locals","text":"We live in Peru, we love Peru. We work with our family and local professionals to operate our tours to Manu National Park. Every trip you take directly supports the local community of Nuevo Eden, Peru."},{"icon":"fas fa-compass","title":"Guided Tours or Independent Trips","text":"We offer both guided tours and can also help organize independent trips for travelers who want to visit Manu with more flexibility. Whatever your style, we tailor the experience to fit you perfectly."},{"icon":"fas fa-leaf","title":"Sustainable Tourism","text":"The Amazon Rainforest is one of our planet''s most important ecosystems, and it''s in danger. We are passionate about using tourism as a positive force to care for the jungle and its inhabitants."}]},"featured_tour_ids":["wildlife-tours","rainforest-road-trip","amazon-expedition"],"map_embed_url":"https://www.google.com/maps/d/embed?mid=12fWz1M5jmQ0jd8rUJY0VUfi6KnRmvnc","tours_header":{"title":"Guided Tours","subtitle":"Curated Jungle Expeditions","description":"Our itineraries are meticulously designed to cater to true nature enthusiasts. From deep-forest survival treks for the intrepid explorer, to focused wildlife spotting cruises along the riverbanks, our routes guarantee a transformative encounter with the wild."}}', '2026-08-22T23:46:25.186Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('contact', '{"titulo_pagina":"Contact Manu Jungle Forever","subtitulo_pagina":"Ready to plan your jungle adventure? Get in touch with our team.","hero_image":"assets/media_to_upload/photos/placeholder.jpg","contacto_principal":{"email":"discover@manujungleforever.com","telefono_1":"+51 931 022 183","telefono_2":"+51 901 525 679","whatsapp":"51901525679","whatsapp_texto":"Hello! I would like to learn more about your jungle trips"},"direccion":{"nombre":"Manu Jungle Forever","calle":"17800","localidad":"Nuevo Eden","pais":"Peru","maps_url":"https://www.google.com/maps/d/viewer?mid=12fWz1M5jmQ0jd8rUJY0VUfi6KnRmvnc","maps_embed":"https://www.google.com/maps/d/embed?mid=12fWz1M5jmQ0jd8rUJY0VUfi6KnRmvnc"},"horario":{"dias":"Monday ÔÇô Sunday","horas":"8:00 AM ÔÇô 8:00 PM (Peru Time)","nota":"We typically respond within 24 hours"},"formulario":{"titulo":"Send Us a Message","subtitulo":"Fill in the form below and we''ll get back to you within 24 hours.","endpoint":"handlers/send-booking.php"},"cta_whatsapp":{"titulo":"Prefer WhatsApp?","texto":"Chat with us directly on WhatsApp for instant answers about tours, availability and pricing.","boton":"WhatsApp Us Now"}}', '2026-08-22T23:46:25.186Z');
